def clean(df):
    df = df.copy()
    df = df.drop_duplicates(keep='first')
    df['island'] = df['island'].str.strip()
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df.loc[(df['body_mass_g'] < 2500) | (df['body_mass_g'] > 6500), 'body_mass_g'] = np.nan
    return df

def answer(df):
    return df.groupby('sex')['body_mass_g'].mean().to_dict()
